  if(lane==='eu_award_sales'&&!q&&!so.length&&!r.length){var initialOut=latestEmailOf(d,'outgoing'),initialIn=latestEmailOf(d,'incoming'),ted=sourceTender(d),orgs=tedOrganizations(ted),contactCount=tedContactCount(ted);if(initialIn)return{title:'Shqyrto përgjigjen / Client RFQ',copy:pick(initialIn.subject,initialIn.snippet,'Ka përgjigje nga klienti potencial. Verifiko interesin dhe regjistro kërkesën para furnitorëve.'),area:'communication',hint:'Hap komunikimin'};if(initialOut)return{title:'Kontrollo follow-up-in e klientit',copy:'Kontakti fillestar është dërguar. Kontrollo përgjigjen dhe përgatit follow-up-in vetëm kur është koha.',area:'communication',hint:'Hap komunikimin'};if(ted&&!contactCount)return{title:'Verifiko fituesit dhe kontaktet',copy:'TED ka '+(orgs.length||Number(tedWinner(ted).organization_count)||1)+' organizata fituese, por 0 kontakte të verifikuara. Asnjë email nuk është dërguar. Verifiko anëtarët dhe kontaktet para outreach.',action:'ted_contacts',hint:'Hap fituesit'};if(ted)return{title:'Kontrollo kontaktet dhe përgatit emailin',copy:'Opportunity është aprovuar si Project. Asnjë email nuk dërgohet automatikisht; kontrollo recipientët dhe draftin para dërgimit.',action:'ted_contacts',hint:'Hap kontaktet'};return{title:'Kontrollo kontaktet dhe përgatit emailin',copy:'Opportunity është aprovuar si Project. Asnjë email nuk dërgohet automatikisht; kontrollo recipientët dhe draftin para dërgimit.',area:'communication',hint:'Hap klientin'};}
  if(lane&&so.length&&!supplierDecision)return{title:'Krahaso dhe aprovo furnitorin',copy:'Ofertat janë regjistruar, por asnjë furnitor nuk është zgjedhur. Kontrollo scope-in, çmimin dhe kushtet; pastaj aprovoje manualisht.',stage:'comparison',hint:'Hap krahasimin'};
  if(lane&&supplierDecision&&!q)return{title:lane==='self_tender'?'Përgatit çmimin dhe dosjen':'Përgatit çmimin dhe ofertën',copy:lane==='self_tender'?'Furnitori u aprovua. Plotëso çmimin dhe dokumentacionin e tenderit para aplikimit.':'Furnitori u aprovua nga njeriu. Përdor bazën e tij të kostos për çmimin dhe ofertën e klientit.',stage:'pricing',hint:'Hap çmimin'};
  if(q&&effectiveOfferSent(q)&&reply)return lane==='self_tender'?{title:'Shqyrto sqarimet / rezultatin e tenderit',copy:pick(reply.subject,reply.snippet,'Ka komunikim të ri pas aplikimit. Verifiko sqarimet ose rezultatin para çdo ndryshimi.'),area:'communication',hint:'Hap komunikimin'}:{title:'Shqyrto negociatën me klientin',copy:pick(reply.subject,reply.snippet,'Ka reagim pas ofertës. Vendos nëse kërkohet revizion ose kthim te furnitorët; asgjë nuk ndryshohet automatikisht.'),area:'communication',hint:'Hap komunikimin e klientit'};
