function routeAttr(x){if(x.action)return'data-pwb3-action="'+E(x.action)+'"';if(x.view)return'data-pwb3-view="'+E(x.view)+'"';if(x.stage)return'data-pwb3-stage="'+E(x.stage)+'"';return'data-pwb3-area="'+E(x.area||'overview')+'"';}
function workflowPath(d){
  var lane=workflowType(d);
  if(lane){
    var qv=effectiveOffer(d),sentv=qv&&effectiveOfferSent(qv),wonv=projectWon(d),lostv=projectLost(d),rv=rfqs(d),sov=supplierOffers(d),supplierDecision=activeSupplierDecision(d),emailsv=emails(d),defs={
      eu_award_sales:['Opportunity','Kontaktimi','Client RFQ','Furnitorët','Krahasimi & oferta','Won / Lost','Ekzekutimi'],
      self_tender:['Tenderi','Kërkesat','Furnitorët','Çmimi & dosja','Aplikimi','Won / Lost'],
      steel_trading:['Client RFQ','Furnitorët','Krahasimi','Oferta','Negociata','Won / Lost','Ekzekutimi']
    },labels=defs[lane],current=lane==='self_tender'||lane==='eu_award_sales'?1:0,complete=false;
    if(lane==='eu_award_sales'&&emailsv.some(outgoing))current=1;
    if(lane==='eu_award_sales'&&emailsv.some(function(m){return incoming(m)&&!automaticReply(m);}))current=2;
    if(rv.length)current=lane==='eu_award_sales'?3:lane==='self_tender'?2:1;
    if(sov.length)current=lane==='eu_award_sales'?4:lane==='self_tender'?3:2;
    if(supplierDecision)current=lane==='eu_award_sales'?4:3;
    if(qv)current=lane==='self_tender'?3:lane==='steel_trading'?3:4;
    if(sentv)current=lane==='self_tender'?4:lane==='steel_trading'?4:4;
    if(wonv)current=labels.length-1;
    if(lostv){current=labels.indexOf('Won / Lost');complete=true;}
    if(lane==='self_tender'&&wonv){current=labels.indexOf('Won / Lost');complete=true;}
    var meta=function(i){if(i===current&&complete)return'Mbyllur';if(i===current)return'Tani';if(i<current)return'Kryer';return'—';};
    return '<div class="pwb3-workflow-title"><span>PPPP V2</span><b>'+E(workflowLabel(d))+'</b><small>Një Project · të gjitha të dhënat dhe vendimet në të njëjtën rrjedhë</small></div><section class="pwb3-path pwb3-path-v2" aria-label="'+E(workflowLabel(d))+'">'+labels.map(function(label,i){var state=i<current||i===current&&complete?'done':i===current?'current':'upcoming';return'<div class="pwb3-phase '+state+'"><span>'+(state==='done'?'✓':'')+'</span><div><b>'+E(label)+'</b><small>'+E(meta(i))+'</small></div></div>';}).join('')+'</section>';
  }
  var q=effectiveOffer(d),sent=q&&effectiveOfferSent(q),won=projectWon(d),closed=projectClosed(d),r=rfqs(d),so=supplierOffers(d),iv=invoicesOut(d),allPaid=iv.length&&iv.every(invoicePaid);
  var prepDone=!!(r.length||so.length||q||won||closed);
  var supplyDone=!!(q||sent||won||closed);
  var commercialDone=!!(won||closed);
  var executionDone=!!(won&&closed)||!!allPaid;
  var xs=[
    {label:'Përgatitja',state:prepDone?'done':'current',meta:prepDone?'Gati':'Në proces'},
    {label:supplyLabel(d)+' & kosto',state:supplyDone?'done':prepDone?'current':'upcoming',meta:so.length?so.length+' oferta':r.length?r.length+' RFQ':'—'},
    {label:'Oferta & klienti',state:commercialDone?'done':q||sent?'current':'upcoming',meta:sent?'Te klienti':q?'Në përgatitje':'—'},
    {label:'Realizimi & financat',state:executionDone?'done':won?'current':'upcoming',meta:won?(allPaid?'Mbyllur':'Në realizim'):'—'}
  ];
  return '<section class="pwb3-path" aria-label="Rrjedha e projektit">'+xs.map(function(x){return'<div class="pwb3-phase '+x.state+'"><span>'+(x.state==='done'?'✓':'')+'</span><div><b>'+E(x.label)+'</b><small>'+E(x.meta)+'</small></div></div>';}).join('')+'</section>';
}
